// js/word-weaver-points.js - Word Weaver's stars, pure (no DOM, no storage). Used by the game
// (word-weaver/js/ui.js), the stats store (js/game-stats.js), the cross-device merge
// (js/players-agg.js), My Stats and the leaderboard, so all of them agree on every number.
//
// THE LADDER: levels 1, 2, 3... (word-weaver/data/, GENERATED by tools/build-word-weaver-data.mjs).
// No replays: a level is scored ONCE, at its first completion. Hints are unlimited; a hint reveals
// one letter.
// BANDS (Matt, 2026-10-29, Gridlock's shape): Easy 1-500, Medium 501-1000, Hard 1001-1500, Expert
// 1501 to the last level shipped. A player may start any band and plays its levels in order. The
// band is a READING of the level number: nothing stored changes (plays before 2026-10-29 sit in
// byDiff 'ladder', kept as stored; the stars always come from the per-level map).
//
// STARS (Matt, 2026-10-28): a level finished with no hint = 3 stars, 1 hint = 2, 2 or more = 1.
//
// WHAT IS STORED (the `ww` sub-counter, js/game-stats.js `recordWordWeaver`):
//   ww.lv['L<n>'] = { s, h, t }   level n: s = stars 1-3, h = hints used, t = when it was first
//                                 completed (ms).
//   ww.es['L<n>'] = { s, h, t }   the SPANISH ladder's level n (2026-10-29, word-weaver/data/es/): a separate
//                                 map, so Spanish level 12 is never English level 12. Points, stars and
//                                 levels completed count BOTH ladders.
//   ww.x = n                      lifetime extra words found (a counter; it only goes up).
//   ww.hint['L<n>'] = { c, t }    HINTS, recorded the moment Hint is tapped (2026-10-29, Matt: "Close the hint
//   ww.esHint['L<n>'] = { c, t }  gap"): c = hints used on level n so far (only grows), t = the first hint's
//                                 time. Before this the count lived only in the level's save, so wiping the save
//                                 and replaying gave 3 stars. A level's stars are now READ as at most what its
//                                 recorded hints allow, when the first hint came before the completion (a hint on a
//                                 second phone AFTER a clean finish elsewhere changes nothing). Nothing stored is
//                                 lowered: the cap is applied at read time (THE LAW rule 2).
// Keys are 'L13', never a bare number: Firebase turns an object with mostly numeric keys into an
// ARRAY. Each field only improves (THE LAW rule 2: stars Math.max, hints Math.min, the earliest
// time), and the cross-device merge takes the best of each, so a level finished on two phones
// counts ONCE.
//
// POINTS are the leaderboard's number (Matt, 2026-10-29: "yes make expert worth more"): a level's
// stars x its band's multiplier, Easy x1, Medium x2, Hard x3, Expert x4, summed over every DISTINCT
// level completed. Read from the per-level map at display time, so nothing stored changes and nothing
// earned is lost (a level finished before the bands existed simply counts at its band's rate).

export const WW_TIERS = ['easy', 'medium', 'hard', 'expert'];
export const WW_BAND_SIZE = 500;
export const WW_BAND_START = { easy: 1, medium: 501, hard: 1001, expert: 1501 };
/** What a star is worth in each band (the leaderboard's points). */
export const WW_MULT = { easy: 1, medium: 2, hard: 3, expert: 4 };

/** The band (difficulty) level n belongs to. */
export function wwBandOf(n) {
  const L = Number(n) || 0;
  return L >= WW_BAND_START.expert ? 'expert' : L >= WW_BAND_START.hard ? 'hard' : L >= WW_BAND_START.medium ? 'medium' : 'easy';
}
/** The last level of a band; Expert's is the last level that exists (`total`), Infinity if not given. */
export function wwBandEnd(band, total = Infinity) {
  return band === 'expert' ? total : WW_BAND_START[band] + WW_BAND_SIZE - 1;
}

/** Stars for a level finished with `hints` hints: 0 -> 3, 1 -> 2, 2+ -> 1. */
export function wwStarsFor(hints) {
  const h = Math.max(0, Math.floor(Number(hints) || 0));
  return h === 0 ? 3 : h === 1 ? 2 : 1;
}

/** One stored level entry, cleaned, or null. A missing star count is read from the hints (rule 4:
 *  nothing is invented beyond what the hints already say); a missing hint count stays unknown (-1
 *  is never stored; the entry just has no h). */
function entry(e) {
  if (!e || typeof e !== 'object' || Array.isArray(e)) return null;
  const hasH = Number.isFinite(Number(e.h)) && e.h !== null && e.h !== '';
  const h = hasH ? Math.max(0, Math.floor(Number(e.h))) : null;
  let s = Math.floor(Number(e.s) || 0);
  if (!(s >= 1)) s = h == null ? 1 : wwStarsFor(h);
  const out = { s: Math.min(3, s) };
  if (h != null) out.h = h;
  const t = Math.floor(Number(e.t) || 0);
  if (t > 0) out.t = t;
  return out;
}

/** The better of two entries for one level, field by field (the cross-device merge, and the
 *  recorder's "only if better"). */
export function wwBest(a, b) {
  const x = entry(a), y = entry(b);
  if (!x) return y;
  if (!y) return x;
  const out = { s: Math.max(x.s, y.s) };
  if (x.h != null || y.h != null) out.h = Math.min(x.h ?? Infinity, y.h ?? Infinity);
  if (x.t || y.t) out.t = Math.min(x.t || Infinity, y.t || Infinity);
  return out;
}

/** One stored hint entry, cleaned, or null. */
function hintEntry(e) {
  if (!e || typeof e !== 'object' || Array.isArray(e)) return null;
  const c = Math.floor(Number(e.c) || 0), t = Math.floor(Number(e.t) || 0);
  return c >= 1 ? { c, t: t > 0 ? t : 0 } : null;
}
/** The merge of two hint entries for one level: the most hints, the earliest first hint. */
export function wwHintBest(a, b) {
  const x = hintEntry(a), y = hintEntry(b);
  if (!x) return y;
  if (!y) return x;
  const t = Math.min(x.t || Infinity, y.t || Infinity);
  return { c: Math.max(x.c, y.c), t: t === Infinity ? 0 : t };
}
/** A record's recorded hints for ONE ladder as { n: { c, t } }. */
export function wwHints(rec, lang = 'en') {
  const raw = (rec && rec.ww && (lang === 'es' ? rec.ww.esHint : rec.ww.hint)) || {};
  const out = {};
  if (!raw || typeof raw !== 'object') return out;
  for (const k of Object.keys(raw)) {
    const m = /^L(\d+)$/.exec(k);
    const e = m && +m[1] >= 1 ? hintEntry(raw[k]) : null;
    if (e) out[+m[1]] = out[+m[1]] ? wwHintBest(out[+m[1]], e) : e;
  }
  return out;
}

/** A record's completed levels of ONE ladder as { n: { s, h?, t? } }, n a number >= 1. `rec` is
 *  `games.wordweaver`; `lang` 'en' (ww.lv, the default) or 'es' (ww.es). */
export function wwLevels(rec, lang = 'en') {
  const lv = (rec && rec.ww && (lang === 'es' ? rec.ww.es : rec.ww.lv)) || {};
  const out = {};
  if (!lv || typeof lv !== 'object') return out;
  for (const k of Object.keys(lv)) {
    const m = /^L(\d+)$/.exec(k);
    if (!m || +m[1] < 1) continue;
    const e = entry(lv[k]);
    if (e) out[+m[1]] = out[+m[1]] ? wwBest(out[+m[1]], e) : e;
  }
  // Hints recorded at tap time cap the stars, when the first came before the completion (see the header).
  const hints = wwHints(rec, lang);
  for (const n of Object.keys(out)) {
    const h = hints[n], e = out[n];
    if (h && (!e.t || !h.t || h.t <= e.t)) {
      const cap = wwStarsFor(h.c);
      if (e.s > cap) out[n] = { ...e, s: cap };
    }
  }
  return out;
}

/** Every completed level of BOTH ladders, [n, entry] (one band, or all). */
function allLevels(rec, band) {
  const out = [];
  for (const lang of ['en', 'es']) {
    const lv = wwLevels(rec, lang);
    for (const k of Object.keys(lv)) if (!band || wwBandOf(+k) === band) out.push([+k, lv[k]]);
  }
  return out;
}
/** Total stars over distinct levels, both ladders (one band, or all). */
export function wwStars(rec, band = null) {
  return allLevels(rec, band).reduce((s, [, e]) => s + e.s, 0);
}
/** Points (one band, or all): stars x the band's multiplier, over distinct levels of both ladders. The leaderboard's number. */
export function wwPoints(rec, band = null) {
  return allLevels(rec, band).reduce((p, [n, e]) => p + e.s * WW_MULT[wwBandOf(n)], 0);
}
/** Levels completed, both ladders (one band, or all). */
export function wwCleared(rec, band = null) {
  return allLevels(rec, band).length;
}
/** Levels completed with three stars, i.e. no hint, both ladders (one band, or all). */
export function wwThreeStars(rec, band = null) {
  return allLevels(rec, band).filter(([, e]) => e.s === 3).length;
}
/** Lifetime extra words found. */
export function wwExtra(rec) {
  const x = Math.floor(Number(rec && rec.ww && rec.ww.x) || 0);
  return x > 0 ? x : 0;
}
